questionvariables.text:
/* theta = -a degrees, for the 12 standard angles a (tangent always defined, P never on an axis).
   unit = 0 shows theta in degrees, unit = 1 in radians: 24 distinct variants. */
alist : [30, 45, 60, 120, 135, 150, 210, 225, 240, 300, 315, 330];
a : rand(alist);
unit : rand([0, 1]);
thetadeg : -a;
theta : thetadeg*%pi/180;
/* numerator and denominator of a/180, for the radian label in the diagram */
gg : gcd(a, 180);
nnum : a/gg;
nden : 180/gg;

/* Where P is: turning clockwise through a degrees ends where an anticlockwise turn of 360 - a ends */
pos : 360 - a;
qP : if pos < 90 then 1 else if pos < 180 then 2 else if pos < 270 then 3 else 4;
refang : if qP = 1 then pos else if qP = 2 then 180 - pos else if qP = 3 then pos - 180 else 360 - pos;
quadnames : ["I", "II", "III", "IV"];
qn : quadnames[qP];
cref : cos(refang*%pi/180);
sref : sin(refang*%pi/180);

x_coord : cos(theta);
y_coord : sin(theta);
sin_theta : y_coord;
cos_theta : x_coord;
tan_theta : sin_theta/cos_theta;

/* Possible student mistakes */
P_plus : [x_coord, -y_coord];     /* used +theta (turned anticlockwise) */
P_xsign : [-x_coord, y_coord];
P_both : [-x_coord, -y_coord];
P_swap : [y_coord, x_coord];
sin_plus : -sin_theta;            /* used +theta */
cos_neg : -cos_theta;
sin_mag : abs(cos_theta);         /* used the cosine value for sine (either sign) */
cos_mag : abs(sin_theta);
tan_plus : -tan_theta;
tan_recip : 1/tan_theta;
